<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,reactive,ref,watch} from 'vue'
import {onBeforeRouteLeave} from 'vue-router'
import {ElMessageBox} from 'element-plus'
import {createRequestId} from '../utils/browserCrypto'
import {api,isCancelled} from '../api/client'
import {session,can,contextGeneration,switchingTenant} from '../stores/session'
import {contextTransitionGuards} from '../utils/contextTransitionGuard'
import {buildMonitoringConfig,emptyMonitoringDraft,monitoringPresets,monitoringTestCommand,monitoringConfigDigest,readProbeReport,monitoringIpv4,type ProbeReport} from '../utils/monitoringOnboarding'
import MonitoringEnrollmentPanel from '../components/MonitoringEnrollmentPanel.vue'
import RegisteredMonitoringTargets from '../components/RegisteredMonitoringTargets.vue'
import ApiErrorNotice from '../components/ApiErrorNotice.vue'
const draft=reactive(emptyMonitoringDraft()),targetId=ref(createRequestId()),baseline=ref(''),notice=ref(''),validation=ref(''),assetError=ref<unknown>(null),assetName=ref(''),assetIp=ref(''),busy=ref(false),importing=ref(false),report=ref<ProbeReport|null>(null),confirming=ref(false),heading=ref<HTMLElement|null>(null)
const permitted=computed(()=>session.value?.mode==='remote_test'&&can('assets:read')&&can('configurations:read')&&!switchingTenant.value)
const scope=computed(()=>JSON.stringify([contextGeneration.value,session.value?.tenant.id,session.value?.user.id,session.value?.account_version,session.value?.permission_version,session.value?.user.role,[...(session.value?.capabilities??[])].sort(),permitted.value]))
const snapshot=()=>JSON.stringify(draft),dirty=computed(()=>snapshot()!==baseline.value)
const preset=computed(()=>monitoringPresets.find(p=>p.id===draft.presetId)!)
const config=computed(()=>{try{return permitted.value?buildMonitoringConfig(draft,session.value!.tenant.id,targetId.value):null}catch{return null}})
const command=computed(()=>config.value?monitoringTestCommand(config.value):'')
let controller:AbortController|null=null,assetTurn=0,reportTurn=0,disposed=false
function cancelAsset(){assetTurn++;controller?.abort();controller=null;busy.value=false}
function reset(){cancelAsset();reportTurn++;Object.assign(draft,emptyMonitoringDraft());targetId.value=createRequestId();baseline.value=snapshot();notice.value='';validation.value='';assetError.value=null;assetName.value='';assetIp.value='';report.value=null;importing.value=false}
watch(scope,reset,{immediate:true,flush:'sync'})
watch(()=>draft.assetId,()=>{cancelAsset();assetName.value='';assetIp.value='';assetError.value=null},{flush:'sync'})
watch(draft,()=>{reportTurn++;report.value=null;importing.value=false;validation.value='';notice.value=''},{deep:true,flush:'sync'})
watch(()=>draft.presetId,()=>{draft.port=String(preset.value.suggested_port);draft.targetHost='';draft.targetPort='';draft.authProfile='';draft.httpPath='/'},{flush:'sync'})
async function mayLeave(){if(!dirty.value)return true;if(confirming.value)return false;const owner=scope.value,before=snapshot();confirming.value=true;try{await ElMessageBox.confirm('当前接入配置尚未保存到服务器，离开会丢弃页面输入。是否继续？','保留监控接入配置',{confirmButtonText:'丢弃并继续',cancelButtonText:'保留输入',type:'warning'});return !disposed&&owner===scope.value&&before===snapshot()}catch{return false}finally{confirming.value=false}}
onBeforeRouteLeave(mayLeave);const unregister=contextTransitionGuards.register(mayLeave)
function unload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}window.addEventListener('beforeunload',unload)
onBeforeUnmount(()=>{disposed=true;cancelAsset();reportTurn++;unregister();window.removeEventListener('beforeunload',unload)})
async function clear(){const owner=scope.value;if(await mayLeave()&&owner===scope.value&&permitted.value){reset();await nextTick();heading.value?.focus()}}
async function readAsset(){if(!permitted.value||busy.value||!/^([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$/.test(draft.assetId))return;cancelAsset();const turn=++assetTurn,id=draft.assetId,owner=scope.value;controller=new AbortController();busy.value=true;assetError.value=null;assetName.value='';assetIp.value='';try{const a=await api.request<{id:string;tenant_id:string;name:string;management_ip:string}>(`/assets/${id}`,{signal:controller.signal});if(disposed||turn!==assetTurn||owner!==scope.value)return;if(a.id!==id||a.tenant_id!==session.value!.tenant.id||typeof a.name!=='string'||!monitoringIpv4(a.management_ip))throw Error('资产响应与当前范围不匹配，或不是受支持的 IPv4');assetName.value=a.name;assetIp.value=a.management_ip}catch(e){if(!disposed&&turn===assetTurn&&!isCancelled(e))assetError.value=e}finally{if(turn===assetTurn)busy.value=false}}
function useAssetIp(){if(!permitted.value||!assetIp.value)return;if(['blackbox','snmp'].includes(preset.value.test_kind))draft.targetHost=assetIp.value;else draft.host=assetIp.value}
function validate(){if(!permitted.value)return false;try{buildMonitoringConfig(draft,session.value!.tenant.id,targetId.value);validation.value='';notice.value='配置格式校验通过，尚未联网或部署';return true}catch(e){validation.value=e instanceof Error?e.message:'配置格式不正确';return false}}
function download(){if(!validate()||!config.value)return;const blob=new Blob([JSON.stringify(config.value,null,2)+'\n'],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');try{a.href=url;a.download=`monitoring-target-${targetId.value}.json`;document.body.append(a);a.click();notice.value='已发起配置下载；未部署、未启用采集。配置文件的地址与标识请妥善保管。'}finally{a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}}
async function importReport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!permitted.value||!config.value)return;const turn=++reportTurn,owner=scope.value,original=JSON.stringify(config.value),selected=config.value;report.value=null;validation.value='';importing.value=true;try{if(file.size>65536)throw Error('报告不得超过64 KiB');const text=await file.text();const digest=await monitoringConfigDigest(selected);if(disposed||turn!==reportTurn||owner!==scope.value||original!==JSON.stringify(config.value))return;report.value=readProbeReport(JSON.parse(text),selected,digest)}catch(e){if(!disposed&&turn===reportTurn)validation.value=e instanceof Error?e.message:'报告读取失败'}finally{if(turn===reportTurn)importing.value=false}}
const reportLabel=computed(()=>report.value?({NOT_RUN:'尚未执行',FAILED:'单次测试失败',TCP_REACHABLE_PROTOCOL_UNVERIFIED:'TCP 可连接，协议与采样未核验',SAMPLE_VERIFIED_ONCE:'单次样本格式核验通过'})[report.value.probe_status]:'')
</script>
<template>
<section class="monitoring-onboarding"><h1 ref="heading" tabindex="-1" class="page-title-sr">监控接入配置</h1>
<p v-if="!permitted" role="status">当前缺少资产读取或配置读取权限，或正在切换租户。</p>
<template v-else>
<RegisteredMonitoringTargets />
<form class="ws-card onboarding-form" @submit.prevent="validate">
<div class="form-grid"><label>监控场景<select v-model="draft.presetId" aria-label="监控场景"><optgroup v-for="scenario in [...new Set(monitoringPresets.map(p=>p.scenario))]" :key="scenario" :label="scenario"><option v-for="p in monitoringPresets.filter(p=>p.scenario===scenario)" :key="p.id" :value="p.id">{{p.title}}</option></optgroup></select></label><label>资产 ID<input v-model="draft.assetId" aria-label="资产 ID" maxlength="36" autocomplete="off" required /></label></div>
<div class="actions"><button type="button" :disabled="busy||draft.assetId.length!==36" @click="readAsset">读取资产信息</button><button v-if="busy" type="button" @click="cancelAsset">取消读取</button><span v-if="assetName">{{assetName}} · {{assetIp}}</span><button v-if="assetIp" type="button" @click="useAssetIp">使用资产 IP</button><a :href="preset.source_url" target="_blank" rel="noopener noreferrer">查看预设来源</a></div><ApiErrorNotice :error="assetError" @retry="readAsset" />
<div class="form-grid"><label>{{['blackbox','snmp'].includes(preset.test_kind)?'Exporter IPv4':'采集端点 IPv4'}}<input v-model="draft.host" aria-label="采集端点 IPv4" maxlength="15" required /></label><label>端口<input v-model="draft.port" aria-label="端口" inputmode="numeric" maxlength="5" required /></label><label v-if="preset.engine==='prometheus'">HTTP 协议<select v-model="draft.scheme" aria-label="HTTP 协议"><option value="http">HTTP</option><option value="https">HTTPS（验证证书）</option></select></label><label>单次超时（秒）<input v-model="draft.timeout" aria-label="单次超时" inputmode="numeric" maxlength="2" required /></label>
<template v-if="['blackbox','snmp'].includes(preset.test_kind)"><label>下游目标 IPv4<input v-model="draft.targetHost" aria-label="下游目标 IPv4" maxlength="15" required /></label><label v-if="['http-service','tcp-service'].includes(preset.id)">下游端口<input v-model="draft.targetPort" aria-label="下游端口" inputmode="numeric" maxlength="5" required /></label><label v-if="preset.id==='http-service'">下游 HTTP 协议<select v-model="draft.targetScheme" aria-label="下游 HTTP 协议"><option value="http">HTTP</option><option value="https">HTTPS（验证证书）</option></select></label><label v-if="preset.id==='http-service'">HTTP 路径<input v-model="draft.httpPath" aria-label="HTTP 路径" maxlength="200" required /></label><label v-if="preset.test_kind==='snmp'">SNMP 认证配置名<input v-model="draft.authProfile" aria-label="SNMP 认证配置名" maxlength="64" autocomplete="off" placeholder="采集侧已有配置名，不填密码" required /></label></template>
<label>采集周期（秒，可留空）<input v-model="draft.interval" aria-label="采集周期" inputmode="numeric" maxlength="4" /></label><label class="check"><input v-model="draft.enabled" type="checkbox" aria-label="输出启用配置" />在导出配置中启用此目标</label></div>
<p class="inline-boundary">当前只生成接入配置，不会修改现有监控或自动部署。{{preset.engine==='zabbix'?'Zabbix 模板ID、组及安全配置仍需在实际实例核对。':'设备和数据库凭据只在采集端管理，不填写到此页面。'}}</p>
<div class="actions content-toolbar"><button type="submit">校验配置</button><button type="button" :disabled="!config" @click="download">下载接入配置</button><div class="content-actions"><button type="button" :disabled="!permitted||confirming" @click="clear">清空配置</button></div></div>
</form>
<MonitoringEnrollmentPanel :draft="draft" />
<p v-if="validation" role="alert">{{validation}}</p><p v-if="notice" role="status">{{notice}}</p>
<section v-if="config" class="ws-card probe-workflow"><h2>连接测试</h2><p>在能访问目标的采集机运行下方命令，将 JSON 输出保存后导入；导入报告只核对其与当前配置一致，报告来源未独立核验。</p><label>测试命令<textarea readonly aria-label="测试命令" :value="command" rows="3" /></label><label>导入测试报告 JSON<input type="file" accept="application/json,.json" aria-label="导入测试报告" :disabled="importing" @change="importReport" /></label><p v-if="importing" role="status">正在核对报告…</p><div v-if="report" class="probe-result" role="status"><strong>{{reportLabel}}</strong><p v-if="report.reason">原因：{{report.reason}}</p><p v-if="report.sample_count!==null">样本 {{report.sample_count}} 条 · 匹配指标 {{report.matched_metrics.join('、')}}</p><p>未证明设备身份、持续采集或业务健康。</p></div><details><summary>查看配置 JSON</summary><pre>{{JSON.stringify(config,null,2)}}</pre></details></section>
</template></section>
</template>
<style scoped>
.monitoring-onboarding{min-width:0}.onboarding-form,.probe-workflow{padding:16px;margin-bottom:12px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.form-grid label,.probe-workflow label{display:grid;gap:6px;min-width:0}.form-grid .check{display:flex;align-items:center;gap:8px}.actions{display:flex;align-items:center;flex-wrap:wrap;gap:8px;margin:12px 0}.monitoring-onboarding input:not([type=checkbox]),.monitoring-onboarding select,.monitoring-onboarding textarea{box-sizing:border-box;width:100%;max-width:100%;min-height:44px}.monitoring-onboarding button{min-height:44px}.monitoring-onboarding :focus-visible{outline:2px solid #2165c5;outline-offset:3px}.probe-workflow textarea{resize:vertical;overflow-wrap:anywhere}.probe-workflow pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:320px;overflow:auto}.probe-result{padding:10px 0;overflow-wrap:anywhere}.probe-workflow h2{margin:0}.probe-workflow p{font-size:13px;line-height:1.5}.probe-workflow label{margin:12px 0}@media(max-width:760px){.form-grid{grid-template-columns:1fr}.onboarding-form,.probe-workflow{padding:12px}}
</style>
